"use client"
// ============ HR Calendar (spec §12.1) ============
// A first-class calendar that CONSUMES events generated by core engines —
// birthdays, anniversaries, tasks, leaves, holidays, payroll dates, document /
// contract expiries, probation completions, loan installments, company events
// and review cycles. Friday is highlighted as the Bangladeshi weekly day-off.
//
// INTERACTIONS:
//   Single-click a date → side panel slides in showing ALL events for that day,
//     grouped by category (Birthdays, Anniversaries, Tasks, Leave, Holidays,
//     Payroll, HR Reminders, Events, Reviews).
//   Double-click a date → "Add to calendar" popup opens, letting the user add
//     a Company Event, Task, Holiday, or HR Reminder (Company Event) for that
//     date.
import { useMemo, useState } from "react"
import {
  Award, Cake, ChevronLeft, ChevronRight, Loader2, Plus,
  CalendarDays, PartyPopper, Briefcase, Plane, Banknote, Bell, FileWarning, CheckCircle2,
} from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { useApi, rpc, useEmployeeDirectory } from "../api"
import { useHrm } from "../store"
import {
  EmptyState, ErrorBanner, PageHeader, SectionCard, fmtDate, titleCase,
} from "../shared/ui-kit"

// Mirrors the server-side color map (events carry their own `color` class).
const KIND_COLORS: Record<string, string> = {
  BIRTHDAY: "bg-pink-500", ANNIVERSARY: "bg-amber-500", TASK: "bg-emerald-600",
  LEAVE: "bg-orange-500", HOLIDAY: "bg-red-600", PAYROLL: "bg-teal-600",
  DOC_EXPIRY: "bg-rose-500", CONTRACT_EXPIRY: "bg-rose-600", PROBATION: "bg-purple-500",
  LOAN_INSTALL: "bg-cyan-600", EVENT: "bg-indigo-500", REVIEW: "bg-violet-500",
  ANNOUNCEMENT: "bg-slate-500", PENDING_LEAVE: "bg-orange-300",
}

const FILTERS: { key: string; label: string; kinds?: string[] }[] = [
  { key: "all", label: "All" },
  { key: "tasks", label: "Tasks", kinds: ["TASK"] },
  { key: "events", label: "Events", kinds: ["EVENT"] },
  { key: "birthdays", label: "Birthdays", kinds: ["BIRTHDAY"] },
  { key: "anniversaries", label: "Anniversaries", kinds: ["ANNIVERSARY"] },
  { key: "leave", label: "Leave", kinds: ["LEAVE", "PENDING_LEAVE"] },
  { key: "holidays", label: "Holidays", kinds: ["HOLIDAY"] },
  { key: "payroll", label: "Payroll", kinds: ["PAYROLL", "LOAN_INSTALL"] },
  { key: "hr", label: "HR Reminders", kinds: ["DOC_EXPIRY", "CONTRACT_EXPIRY", "PROBATION", "REVIEW"] },
]

const LEGEND: [string, string][] = [
  ["BIRTHDAY", "Birthday"],
  ["ANNIVERSARY", "Anniversary"],
  ["TASK", "Task due"],
  ["LEAVE", "Leave (approved)"],
  ["PENDING_LEAVE", "Leave (pending)"],
  ["HOLIDAY", "Holiday"],
  ["PAYROLL", "Payroll date"],
  ["LOAN_INSTALL", "Loan installment"],
  ["EVENT", "Company event"],
  ["REVIEW", "Review cycle"],
  ["DOC_EXPIRY", "Document expiry"],
  ["CONTRACT_EXPIRY", "Contract expiry"],
  ["PROBATION", "Probation end"],
]

const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]
const DOW = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]

// Categories for the day-detail side panel — groups multiple event kinds.
const DAY_CATEGORIES: { key: string; label: string; kinds: string[]; icon: any; color: string }[] = [
  { key: "birthdays", label: "Birthdays", kinds: ["BIRTHDAY"], icon: Cake, color: "text-pink-600" },
  { key: "anniversaries", label: "Anniversaries", kinds: ["ANNIVERSARY"], icon: Award, color: "text-amber-600" },
  { key: "tasks", label: "Tasks", kinds: ["TASK"], icon: Briefcase, color: "text-emerald-600" },
  { key: "leave", label: "Leave", kinds: ["LEAVE", "PENDING_LEAVE"], icon: Plane, color: "text-orange-600" },
  { key: "holidays", label: "Holidays", kinds: ["HOLIDAY"], icon: PartyPopper, color: "text-red-600" },
  { key: "payroll", label: "Payroll & Loans", kinds: ["PAYROLL", "LOAN_INSTALL"], icon: Banknote, color: "text-teal-600" },
  { key: "events", label: "Company Events", kinds: ["EVENT"], icon: CalendarDays, color: "text-indigo-600" },
  { key: "reviews", label: "Reviews", kinds: ["REVIEW"], icon: CheckCircle2, color: "text-violet-600" },
  { key: "reminders", label: "HR Reminders", kinds: ["DOC_EXPIRY", "CONTRACT_EXPIRY", "PROBATION"], icon: FileWarning, color: "text-rose-600" },
]

function dotClass(e: any): string {
  return e?.color || KIND_COLORS[e?.kind] || "bg-slate-400"
}

export default function CalendarView() {
  const now = new Date()
  const [month, setMonth] = useState(now.getMonth() + 1)
  const [year, setYear] = useState(now.getFullYear())
  const [filter, setFilter] = useState("all")
  const [selectedDate, setSelectedDate] = useState<string | null>(null)
  const [addOpen, setAddOpen] = useState<{ date: string } | null>(null)
  const { can: _can, toast: _toast } = useHrm()

  // Multiple weekly holidays (Settings → General → Weekly Holiday): every
  // selected weekday is an off day. Falls back to Friday (the BD convention)
  // for vendors that never configured the policy. DOW is Sun-based and holds
  // 3-letter names; settings store full weekday names — compare by 3-letter
  // prefix so both "FRIDAY" and "Fri" resolve.
  const weeklyHoliday: string[] = useHrm((s) => s.settings?.general?.weeklyHoliday) || []
  const offDows = useMemo(() => {
    const names = weeklyHoliday.length ? weeklyHoliday : ["FRIDAY"]
    const idx = names
      .map((n) => DOW.findIndex((d) => d.toUpperCase() === String(n).trim().toUpperCase().slice(0, 3)))
      .filter((i) => i >= 0)
    return idx.length ? [...new Set(idx)] : [5]
  }, [weeklyHoliday])
  const isOffDow = (idx: number) => offDows.includes(idx % 7)
  const offLabel = (idx: number) => `${DOW[idx % 7].toUpperCase()}.OFF`

  const active = FILTERS.find((f) => f.key === filter)
  const kinds = active?.kinds
  const payload = useMemo(
    () => ({ month, year, ...(kinds && kinds.length ? { kinds } : {}) }),
    [month, year, kinds],
  )
  const { data: events, loading, error, reload } = useApi<any[]>("calendar.events", payload)
  const { data: wishes } = useApi<any>("wishes.today", {})

  const byDate = useMemo(() => {
    const m: Record<string, any[]> = {}
    for (const e of events || []) (m[e.date] = m[e.date] || []).push(e)
    return m
  }, [events])

  const weeks = useMemo(() => {
    const lead = new Date(year, month - 1, 1).getDay() // 0 = Sunday
    const days = new Date(year, month, 0).getDate()
    const cells: (number | null)[] = Array.from({ length: lead + days }, (_, i) => (i < lead ? null : i - lead + 1))
    while (cells.length % 7 !== 0) cells.push(null)
    const out: (number | null)[][] = []
    for (let i = 0; i < cells.length; i += 7) out.push(cells.slice(i, i + 7))
    return out
  }, [year, month])

  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`

  const shift = (delta: number) => {
    let m = month + delta
    let y = year
    if (m < 1) { m = 12; y -= 1 } else if (m > 12) { m = 1; y += 1 }
    setMonth(m)
    setYear(y)
  }

  const dateStrOf = (d: number) => `${year}-${String(month).padStart(2, "0")}-${String(d).padStart(2, "0")}`

  const hasWishes = !!wishes && ((wishes.birthdays?.length || 0) + (wishes.anniversaries?.length || 0) > 0)

  // The currently selected day's events (from the calendar payload — already loaded).
  const selectedEvents = selectedDate ? (byDate[selectedDate] || []) : []

  return (
    <div className="space-y-4">
      <PageHeader
        title="HR Calendar"
        subtitle="Click a date to see all events · Double-click to add an event, task, holiday, or HR reminder"
      />

      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
        <div className="space-y-3 min-w-0">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-1.5">
              <Button variant="outline" size="icon" className="h-8 w-8" onClick={() => shift(-1)} aria-label="Previous month">
                <ChevronLeft className="h-4 w-4" />
              </Button>
              <div className="flex items-center gap-2 min-w-[168px] justify-center">
                <span className="text-sm font-bold text-slate-800 dark:text-slate-100">{MONTH_NAMES[month - 1]} {year}</span>
                {loading && <Loader2 className="h-3.5 w-3.5 animate-spin text-slate-400" />}
              </div>
              <Button variant="outline" size="icon" className="h-8 w-8" onClick={() => shift(1)} aria-label="Next month">
                <ChevronRight className="h-4 w-4" />
              </Button>
              <Button variant="outline" size="sm" className="h-8 text-xs ml-1"
                onClick={() => { setMonth(now.getMonth() + 1); setYear(now.getFullYear()) }}>
                Today
              </Button>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {FILTERS.map((f) => (
                <button key={f.key} type="button" onClick={() => setFilter(f.key)}
                  className={`rounded-full px-3 py-1 text-xs font-medium transition-colors whitespace-nowrap ${
                    filter === f.key
                      ? "bg-primary text-primary-foreground"
                      : "border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 hover:border-emerald-400"
                  }`}>
                  {f.label}
                </button>
              ))}
            </div>
          </div>

          {error && <ErrorBanner message={error} />}

          <div className="rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 overflow-hidden">
            <div className="grid grid-cols-7 border-b border-slate-100 dark:border-slate-800 bg-slate-50/80 dark:bg-slate-800/60">
              {DOW.map((d, i) => (
                <div key={d} className={`py-2 text-center text-[11px] font-semibold uppercase tracking-wide ${
                  isOffDow(i) ? "text-rose-500" : "text-slate-500 dark:text-slate-400"
                }`}>
                  {d}{isOffDow(i) ? " · off" : ""}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-7">
              {weeks.flat().map((d, idx) => {
                if (d == null) {
                  return <div key={idx} className="min-h-[92px] sm:min-h-[110px] border-b border-r border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/40" />
                }
                const dateStr = dateStrOf(d)
                const evs = byDate[dateStr] || []
                const isToday = dateStr === todayStr
                const isWeeklyOff = isOffDow(idx)
                const isSelected = dateStr === selectedDate
                return (
                  <div key={idx}
                    // Single click → select the day (shows events in the side panel).
                    // Double click → open the "add to calendar" popup for that date.
                    onClick={() => setSelectedDate(dateStr)}
                    onDoubleClick={() => setAddOpen({ date: dateStr })}
                    className={`min-h-[92px] sm:min-h-[110px] border-b border-r border-slate-100 dark:border-slate-800 p-1.5 space-y-1 cursor-pointer transition-colors ${
                      isWeeklyOff ? "bg-rose-50/40 dark:bg-rose-950/10" : ""
                    } ${isToday ? "ring-2 ring-inset ring-emerald-500" : ""} ${
                      isSelected ? "bg-emerald-50 dark:bg-emerald-950/30 ring-2 ring-inset ring-emerald-600" : "hover:bg-slate-50 dark:hover:bg-slate-800/40"
                    }`}>
                    <div className="flex items-center justify-between gap-1">
                      <span className={`text-xs font-bold tabular-nums ${
                        isToday ? "text-emerald-700 dark:text-emerald-400"
                          : isWeeklyOff ? "text-rose-500"
                            : "text-slate-600 dark:text-slate-300"
                      }`}>{d}</span>
                      {isWeeklyOff
                        ? <span className="text-[8px] font-bold text-rose-500/90 dark:text-rose-400/80 tracking-tight">{offLabel(idx)}</span>
                        : evs.length > 0 && <span className="text-[9px] text-slate-500 dark:text-slate-400 tabular-nums">{evs.length}</span>}
                    </div>
                    {evs.slice(0, 3).map((e: any, i: number) => (
                      <div key={i} title={`${e.title}${e.detail ? " — " + e.detail : ""}`}
                        className="flex items-center gap-1.5 rounded-md border border-slate-100 dark:border-slate-800 bg-white/80 dark:bg-slate-800/60 px-1.5 py-0.5 min-w-0">
                        <span className={`h-1.5 w-1.5 rounded-full shrink-0 ${dotClass(e)}`} />
                        <span className="text-[10px] leading-tight truncate text-slate-600 dark:text-slate-300">{e.title}</span>
                      </div>
                    ))}
                    {evs.length > 3 && (
                      <button type="button"
                        className="text-[10px] font-medium text-emerald-700 dark:text-emerald-400 hover:underline"
                        onClick={(ev) => { ev.stopPropagation(); setSelectedDate(dateStr) }}>
                        +{evs.length - 3} more
                      </button>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
          <p className="text-[10px] text-slate-500 dark:text-slate-400">
            Tip: single-click a date to see all events in the side panel · double-click to add a new event, task, holiday, or HR reminder.
          </p>
        </div>

        <div className="space-y-4">
          {/* ── Selected Day Detail Panel ── */}
          {selectedDate ? (
            <SectionCard title={`Day Detail — ${fmtDate(selectedDate)}`}>
              {selectedEvents.length === 0 ? (
                <EmptyState icon={CalendarDays} title="No events on this day"
                  hint="Double-click the date to add an event, task, holiday, or HR reminder." />
              ) : (
                <div className="space-y-3 max-h-[500px] overflow-y-auto">
                  {DAY_CATEGORIES.map((cat) => {
                    const catEvents = selectedEvents.filter((e) => cat.kinds.includes(e.kind))
                    if (catEvents.length === 0) return null
                    const Icon = cat.icon
                    return (
                      <div key={cat.key} className="space-y-1.5">
                        <div className="flex items-center gap-1.5 sticky top-0 bg-white dark:bg-slate-900 py-1">
                          <Icon className={`h-3.5 w-3.5 ${cat.color}`} />
                          <span className="text-xs font-semibold text-slate-700 dark:text-slate-200">{cat.label}</span>
                          <Badge variant="outline" className="text-[9px] ml-auto">{catEvents.length}</Badge>
                        </div>
                        {catEvents.map((e: any, i: number) => (
                          <div key={i} className="flex items-start gap-2 rounded-md border border-slate-100 dark:border-slate-800 bg-slate-50/60 dark:bg-slate-800/40 px-2 py-1.5">
                            <span className={`mt-1 h-2 w-2 rounded-full shrink-0 ${dotClass(e)}`} />
                            <div className="min-w-0">
                              <p className="text-xs font-medium text-slate-800 dark:text-slate-100 break-words">{e.title}</p>
                              {e.detail && <p className="text-[10px] text-slate-500">{e.detail}</p>}
                            </div>
                          </div>
                        ))}
                      </div>
                    )
                  })}
                </div>
              )}
              <div className="pt-2 mt-2 border-t border-slate-100 dark:border-slate-800">
                <Button size="sm" variant="outline" className="w-full h-8 text-xs"
                  onClick={() => setAddOpen({ date: selectedDate })}>
                  <Plus className="h-3.5 w-3.5 mr-1" /> Add to this date
                </Button>
              </div>
            </SectionCard>
          ) : (
            <SectionCard title="Today's Wishes">
              {!wishes ? (
                <p className="text-xs text-slate-400">Loading…</p>
              ) : !hasWishes ? (
                <EmptyState icon={Cake} title="No wishes today"
                  hint="Employee birthdays and joining anniversaries will appear here with their template-rendered greeting messages." />
              ) : (
                <div className="space-y-2">
                  {(wishes.birthdays || []).map((b: any) => (
                    <div key={b.employeeId} className="rounded-lg border border-pink-200 dark:border-pink-900 bg-pink-50/60 dark:bg-pink-950/30 p-3">
                      <div className="flex items-center gap-2 flex-wrap">
                        <Cake className="h-4 w-4 text-pink-500 shrink-0" />
                        <p className="text-sm font-semibold text-slate-800 dark:text-slate-100">{b.name}</p>
                        <Badge className="bg-pink-100 text-pink-700 text-[9px]">Birthday</Badge>
                      </div>
                      <p className="text-xs italic text-slate-500 dark:text-slate-400 mt-1.5">“{b.message}”</p>
                    </div>
                  ))}
                  {(wishes.anniversaries || []).map((a: any) => (
                    <div key={a.employeeId} className="rounded-lg border border-amber-200 dark:border-amber-900 bg-amber-50/60 dark:bg-amber-950/30 p-3">
                      <div className="flex items-center gap-2 flex-wrap">
                        <Award className="h-4 w-4 text-amber-500 shrink-0" />
                        <p className="text-sm font-semibold text-slate-800 dark:text-slate-100">{a.name}</p>
                        <Badge className="bg-amber-100 text-amber-700 text-[9px]">
                          {a.years} year{a.years !== 1 ? "s" : ""}
                        </Badge>
                      </div>
                      <p className="text-xs italic text-slate-500 dark:text-slate-400 mt-1.5">“{a.message}”</p>
                    </div>
                  ))}
                </div>
              )}
            </SectionCard>
          )}

          <SectionCard title="Legend">
            <div className="flex flex-wrap gap-x-4 gap-y-1.5">
              {LEGEND.map(([kind, label]) => (
                <span key={kind} className="inline-flex items-center gap-1.5 text-[11px] text-slate-600 dark:text-slate-300 whitespace-nowrap">
                  <span className={`h-2 w-2 rounded-full ${KIND_COLORS[kind]}`} />
                  {label}
                </span>
              ))}
            </div>
            <p className="text-[10px] text-slate-500 dark:text-slate-400 mt-2">
              {offDows.length} weekly off day{offDows.length !== 1 ? "s" : ""} ({offDows.map((i) => DOW[i]).join(", ")}) are highlighted from Settings → General → Weekly Holiday. Today is outlined in emerald.
            </p>
          </SectionCard>
        </div>
      </div>

      {/* Day detail modal (kept for backward-compat — clicking "+N more" or any event chip opens this) */}
      <Dialog open={!!selectedDate && selectedEvents.length > 0 && false} onOpenChange={(v) => { if (!v) setSelectedDate(null) }}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="text-base">{selectedDate ? fmtDate(selectedDate) : ""}</DialogTitle>
          </DialogHeader>
          <div className="space-y-2 max-h-[60vh] overflow-y-auto">
            {selectedEvents.map((e: any, i: number) => (
              <div key={i} className="flex items-start gap-2.5 rounded-lg border border-slate-200 dark:border-slate-800 px-3 py-2">
                <span className={`mt-1 h-2 w-2 rounded-full shrink-0 ${dotClass(e)}`} />
                <div className="min-w-0">
                  <p className="text-sm font-medium text-slate-800 dark:text-slate-100 break-words">{e.title}</p>
                  <p className="text-[11px] text-slate-500 dark:text-slate-400">{titleCase(e.kind)}{e.detail ? ` · ${e.detail}` : ""}</p>
                </div>
              </div>
            ))}
          </div>
        </DialogContent>
      </Dialog>

      {/* Add to calendar popup — opens on double-click */}
      {addOpen && (
        <AddToCalendarDialog
          date={addOpen.date}
          onOpenChange={(v) => { if (!v) setAddOpen(null) }}
          onCreated={() => {
            // M-08 — the setMonth((m) => m) self-assignment never re-rendered
            // anything (same state value); call the events reload() that useApi
            // actually returns so new events appear immediately.
            reload()
            setAddOpen(null)
          }}
        />
      )}
    </div>
  )
}

// ============================================================
// Add to Calendar Dialog — opens when the user double-clicks a date.
// Lets them add one of: Company Event, Task, Holiday, HR Reminder.
// ============================================================
function AddToCalendarDialog({ date, onOpenChange, onCreated }: {
  date: string
  onOpenChange: (v: boolean) => void
  onCreated: () => void
}) {
  const { can, toast } = useHrm()
  const [tab, setTab] = useState<"event" | "task" | "holiday" | "reminder">("event")
  const [busy, setBusy] = useState(false)
  const { data: employees } = useEmployeeDirectory()
  const { data: branches } = useApi<any[]>("branches.list", {})

  // Event form state
  const [evTitle, setEvTitle] = useState("")
  const [evType, setEvType] = useState("EVENT")
  const [evTime, setEvTime] = useState("")
  const [evDesc, setEvDesc] = useState("")
  const [evBranch, setEvBranch] = useState("")

  // Task form state
  const [taskTitle, setTaskTitle] = useState("")
  const [taskAssignee, setTaskAssignee] = useState("")
  const [taskPriority, setTaskPriority] = useState("MEDIUM")
  const [taskDesc, setTaskDesc] = useState("")

  // Holiday form state
  const [holName, setHolName] = useState("")
  const [holType, setHolType] = useState("PUBLIC")

  // Reminder form state (implemented as a Company Event of type PAYROLL_TASK
  // or a Task with scope DEPARTMENT — we use Company Event with a custom type)
  const [remTitle, setRemTitle] = useState("")
  const [remDesc, setRemDesc] = useState("")

  const canCreateEvent = can("announcements", "create")
  const canCreateTask = can("tasks", "create")
  const canCreateHoliday = can("organization", "create")

  const TABS: { key: typeof tab; label: string; icon: any; allowed: boolean }[] = [
    { key: "event", label: "Event", icon: CalendarDays, allowed: canCreateEvent },
    { key: "task", label: "Task", icon: Briefcase, allowed: canCreateTask },
    { key: "holiday", label: "Holiday", icon: PartyPopper, allowed: canCreateHoliday },
    { key: "reminder", label: "HR Reminder", icon: Bell, allowed: canCreateEvent },
  ]

  const submit = async () => {
    setBusy(true)
    try {
      if (tab === "event") {
        if (!evTitle.trim()) { toast("Event title is required", "err"); return }
        await rpc("events.create", {
          title: evTitle.trim(),
          type: evType,
          date,
          time: evTime || null,
          description: evDesc || null,
          branchId: evBranch || null,
        })
        toast(`Event "${evTitle}" added on ${date}`)
      } else if (tab === "task") {
        if (!taskTitle.trim()) { toast("Task title is required", "err"); return }
        if (!taskAssignee) { toast("Assignee is required", "err"); return }
        await rpc("tasks.save", {
          title: taskTitle.trim(),
          description: taskDesc || null,
          assigneeId: taskAssignee,
          priority: taskPriority,
          startDate: date,
          dueDate: date,
          scope: "EMPLOYEE",
        })
        toast(`Task "${taskTitle}" added — due ${date}`)
      } else if (tab === "holiday") {
        if (!holName.trim()) { toast("Holiday name is required", "err"); return }
        await rpc("holidays.create", {
          name: holName.trim(),
          date,
          type: holType,
        })
        toast(`Holiday "${holName}" added on ${date}`)
      } else if (tab === "reminder") {
        if (!remTitle.trim()) { toast("Reminder title is required", "err"); return }
        // HR Reminders are stored as Company Events with type "PAYROLL_TASK"
        // so they show up on the calendar with the PAYROLL color.
        await rpc("events.create", {
          title: `🔔 ${remTitle.trim()}`,
          type: "PAYROLL_TASK",
          date,
          description: remDesc || "HR reminder",
        })
        toast(`HR Reminder "${remTitle}" added on ${date}`)
      }
      onCreated()
    } catch (e: any) {
      toast(e.message, "err")
    } finally {
      setBusy(false)
    }
  }

  return (
    <Dialog open onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="text-base flex items-center gap-2">
            <Plus className="h-4 w-4 text-emerald-600" /> Add to Calendar — {fmtDate(date)}
          </DialogTitle>
        </DialogHeader>
        <div className="flex flex-wrap gap-1 border-b border-slate-100 dark:border-slate-800 pb-2">
          {TABS.map((t) => {
            const Icon = t.icon
            return (
              <button key={t.key} type="button" disabled={!t.allowed}
                onClick={() => setTab(t.key)}
                className={`flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-medium transition-colors ${
                  tab === t.key
                    ? "bg-primary text-primary-foreground"
                    : "text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800"
                } ${!t.allowed ? "opacity-40 cursor-not-allowed" : ""}`}>
                <Icon className="h-3.5 w-3.5" /> {t.label}
              </button>
            )
          })}
        </div>

        <div className="space-y-3 py-1">
          {tab === "event" && (
            <>
              <div>
                <Label className="text-xs">Event Title *</Label>
                <Input value={evTitle} onChange={(e) => setEvTitle(e.target.value)} placeholder="Monthly All-Hands Meeting" className="h-9 mt-1" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Type</Label>
                  <Select value={evType} onValueChange={setEvType}>
                    <SelectTrigger className="h-9 mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="EVENT">Event</SelectItem>
                      <SelectItem value="MEETING">Meeting</SelectItem>
                      <SelectItem value="TRAINING">Training</SelectItem>
                      <SelectItem value="PAYROLL_TASK">Payroll Task</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-xs">Time</Label>
                  <Input type="time" value={evTime} onChange={(e) => setEvTime(e.target.value)} className="h-9 mt-1" />
                </div>
              </div>
              <div>
                <Label className="text-xs">Branch (optional)</Label>
                <Select value={evBranch} onValueChange={setEvBranch}>
                  <SelectTrigger className="h-9 mt-1"><SelectValue placeholder="All branches" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="NONE">All branches</SelectItem>
                    {(branches || []).map((b: any) => (
                      <SelectItem key={b.id} value={b.id}>{b.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs">Description</Label>
                <Textarea value={evDesc} onChange={(e) => setEvDesc(e.target.value)} rows={2} className="mt-1" placeholder="Optional notes" />
              </div>
            </>
          )}

          {tab === "task" && (
            <>
              <div>
                <Label className="text-xs">Task Title *</Label>
                <Input value={taskTitle} onChange={(e) => setTaskTitle(e.target.value)} placeholder="Quarterly stock audit" className="h-9 mt-1" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Assignee *</Label>
                  <Select value={taskAssignee} onValueChange={setTaskAssignee}>
                    <SelectTrigger className="h-9 mt-1"><SelectValue placeholder="Select employee" /></SelectTrigger>
                    <SelectContent>
                      {(employees || []).map((e: any) => (
                        <SelectItem key={e.id} value={e.id}>{e.fullName} ({e.code})</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-xs">Priority</Label>
                  <Select value={taskPriority} onValueChange={setTaskPriority}>
                    <SelectTrigger className="h-9 mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="LOW">Low</SelectItem>
                      <SelectItem value="MEDIUM">Medium</SelectItem>
                      <SelectItem value="HIGH">High</SelectItem>
                      <SelectItem value="URGENT">Urgent</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div>
                <Label className="text-xs">Description</Label>
                <Textarea value={taskDesc} onChange={(e) => setTaskDesc(e.target.value)} rows={2} className="mt-1" placeholder="Optional task details" />
              </div>
              <p className="text-[10px] text-slate-500 dark:text-slate-400">Due date set to {fmtDate(date)}. Start date set to today.</p>
            </>
          )}

          {tab === "holiday" && (
            <>
              <div>
                <Label className="text-xs">Holiday Name *</Label>
                <Input value={holName} onChange={(e) => setHolName(e.target.value)} placeholder="Victory Day" className="h-9 mt-1" />
              </div>
              <div>
                <Label className="text-xs">Type</Label>
                <Select value={holType} onValueChange={setHolType}>
                  <SelectTrigger className="h-9 mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="PUBLIC">Public Holiday</SelectItem>
                    <SelectItem value="COMPANY">Company Holiday</SelectItem>
                    <SelectItem value="RESTRICTED">Restricted Holiday</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <p className="text-[10px] text-slate-500 dark:text-slate-400">Holiday date set to {fmtDate(date)}.</p>
            </>
          )}

          {tab === "reminder" && (
            <>
              <div>
                <Label className="text-xs">Reminder Title *</Label>
                <Input value={remTitle} onChange={(e) => setRemTitle(e.target.value)} placeholder="Confirm payroll cutoff with finance" className="h-9 mt-1" />
              </div>
              <div>
                <Label className="text-xs">Notes</Label>
                <Textarea value={remDesc} onChange={(e) => setRemDesc(e.target.value)} rows={3} className="mt-1" placeholder="Optional details" />
              </div>
              <p className="text-[10px] text-slate-500 dark:text-slate-400">HR Reminders appear on the calendar with the PAYROLL color (teal).</p>
            </>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={busy}>Cancel</Button>
          <Button disabled={busy}
            onClick={submit}>
            {busy ? "Saving…" : "Add to Calendar"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
